import React, {useState} from 'react';
import {Alert, Button, Form} from 'react-bootstrap'
import {Link} from "react-router-dom";
import {useForm} from 'react-hook-form'


const SignUpPage = () => {

    const {register, watch, handleSubmit, reset, formState: {errors}} = useForm();
    const [show, setShow] = useState(true)
    const [serverResponse,setServerResponse]=useState('')
    const submitForm = (data) => {

        if (data.password === data.confirmPassword) {

            const body = {
                username: data.username,
                email: data.email,
                password: data.password
            }

            const requestOptions = {
                method: "POST",
                headers: {
                    'content-type': 'application/json'
                },
                body: JSON.stringify(body)
            }

            fetch('/auth/signup', requestOptions)
                .then(res => res.json())
                .then(data => {
                    
                    setServerResponse(data.message)
                    console.log(serverResponse)
                })
                .catch(err => console.log(err))


            reset()
        } else {
            alert("Password do not match")
        }


    }


    return (
        <div className="container">
            <div className={"form"}>

                {show ?
                    <>
                        <h1>Sign Up Page</h1>

                        <Alert variant="danger" onClose={() => setShow(false)} dismissible>
                            <Alert.Heading>Oh snap! You got an error!</Alert.Heading>
                            <p>
                                Change this and that and try again. Duis mollis, est non commodo
                                luctus, nisi erat porttitor ligula, eget lacinia odio sem nec elit.
                                Cras mattis consectetur purus sit amet fermentum.
                            </p>
                        </Alert>
                    </>
                    :
                    <h1>Sign Up Page</h1>

                }


                <form>
                    <Form.Group>
                        <Form.Label>Username</Form.Label>
                        <Form.Control type={"text"}
                                      placeholder={"Your username"}
                                      {...register("username", {required: true, maxLength: 25})}
                        />

                        {errors.username && <p style={{color: "red"}}><small>Username is required</small></p>}

                        {errors.username?.type === "maxLength" &&
                        <p style={{color: "red"}}><small>Max characters should be 25</small></p>}
                    </Form.Group>

                    <br></br>
                    <Form.Group>
                        <Form.Label>Email</Form.Label>
                        <Form.Control type={"email"}
                                      placeholder={"Your email"}
                                      {...register("email", {required: true, maxLength: 80})}   />

                        {errors.email && <p style={{color: "red"}}><small>Email is required</small></p>}

                        {errors.email?.type === "maxLength" &&
                        <p style={{color: "red"}}><small>Max characters should be 80</small></p>}
                    </Form.Group>
                    <br></br>
                    <Form.Group>
                        <Form.Label>Password</Form.Label>
                        <Form.Control type={"password"}
                                      placeholder={"Your password"}
                                      {...register("password", {required: true, minLength: 8})}
                        />

                        {errors.password && <p style={{color: "red"}}><small>password is required</small></p>}

                        {errors.password?.type === "minLength" &&
                        <p style={{color: "red"}}><small>Min characters should be 8</small></p>}
                    </Form.Group>
                    <br></br>
                    <Form.Group>
                        <Form.Label>Confirm Password</Form.Label>
                        <Form.Control type={"password"} placeholder={"Your password"}
                                      {...register("confirmPassword", {required: true, minLength: 8})}
                        />

                        {errors.confirmPassword &&
                        <p style={{color: "red"}}><small>confirm Password is required</small></p>}

                        {errors.confirmPassword?.type === "minLength" &&
                        <p style={{color: "red"}}><small>Min characters should be 8</small></p>}
                    </Form.Group>
                    <br></br>

                    <Form.Group>
                        <Button as={"sub"} variant={"primary"} onClick={handleSubmit(submitForm)}>SignUp</Button>
                    </Form.Group>
                    <br></br>
                    <Form.Group>
                        <small>Already have an account? <Link to='/login'>Log in</Link></small>
                    </Form.Group>
                </form>
            </div>
        </div>
    )
}

export default SignUpPage
